PRAGMA foreign_keys = ON;

CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('employee','approver','admin')), disabled_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE password_credentials (user_id TEXT PRIMARY KEY REFERENCES users(id), hash TEXT NOT NULL, algorithm TEXT NOT NULL, params_json TEXT NOT NULL, updated_at TEXT NOT NULL, failed_attempts INTEGER NOT NULL DEFAULT 0, blocked_until TEXT);
CREATE TABLE sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, last_seen_at TEXT NOT NULL);
CREATE TABLE templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, version INTEGER NOT NULL, r2_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)));
CREATE TABLE timesheets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), target_month TEXT NOT NULL CHECK (target_month GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]'), template_id TEXT NOT NULL REFERENCES templates(id), status TEXT NOT NULL CHECK (status IN ('draft','submitted','rejected','approved','archived')), current_version INTEGER NOT NULL, current_r2_key TEXT NOT NULL, current_sha256 TEXT NOT NULL, lock_id TEXT, lock_user_id TEXT REFERENCES users(id), lock_token_hash TEXT, lock_base_version INTEGER, lock_expires_at TEXT, lock_revoked_at TEXT, submitted_version INTEGER, approved_version INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id, target_month));
CREATE TABLE file_versions (id TEXT PRIMARY KEY, timesheet_id TEXT NOT NULL REFERENCES timesheets(id), version INTEGER NOT NULL, r2_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(timesheet_id, version));
CREATE TABLE submissions (id TEXT PRIMARY KEY, timesheet_id TEXT NOT NULL REFERENCES timesheets(id), version INTEGER NOT NULL, submitted_by TEXT NOT NULL REFERENCES users(id), submitted_at TEXT NOT NULL, decision TEXT, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, rejection_reason TEXT, version_sha256 TEXT NOT NULL);
CREATE TABLE approver_assignments (id TEXT PRIMARY KEY, approver_id TEXT NOT NULL REFERENCES users(id), employee_id TEXT NOT NULL REFERENCES users(id), UNIQUE(approver_id, employee_id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, details_json TEXT NOT NULL, request_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE idempotency_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), route TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, status_code INTEGER NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, UNIQUE(user_id, route, key));
CREATE INDEX idx_timesheets_status ON timesheets(status);
CREATE INDEX idx_file_versions_timesheet ON file_versions(timesheet_id, version);
CREATE INDEX idx_audit_entity ON audit_events(entity_type, entity_id, created_at);
